    + g(`<circle cx="232" cy="88" r="9" style="fill:#FFFDF6;stroke:${C.wood2}" stroke-width="2"/><path d="M232 88 v-5 M232 88 l4 2" style="stroke:#2F2B28" stroke-width="1"/>${kettle(288, 98, .7)}`) + `<g class="flick" pointer-events="none"><ellipse cx="258" cy="196" rx="40" ry="18" fill="#FFC66B" opacity=".25"/></g>`
